#include <cuda_runtime.h>
#include <vector>
#include <fstream>
#include <string>
#include <chrono>
#include <cmath>
#include <cstring>
#include "study_bridge.h"
#include "study_params.h"
#define C(x) do{int e=(x);if(e){fprintf(stderr,"CUDAorbridgeerror%d line%d\n",e,__LINE__);exit(1);}}while(0)
template<class A>std::vector<A>read_file(const std::string&p,int n){std::ifstream f(p,std::ios::binary);std::vector<A>a(n);f.read((char*)a.data(),n*sizeof(A));if(f.gcount()!=n*sizeof(A))exit(2);return a;}
template<class A>struct Buffer{A*base,*ptr;std::vector<A>initial;Buffer(std::vector<A>x,A guard){initial.assign(16,guard);initial.insert(initial.end(),x.begin(),x.end());initial.insert(initial.end(),16,guard);C(cudaMalloc(&base,initial.size()*sizeof(A)));ptr=base+16;reset();}void reset(){C(cudaMemcpy(base,initial.data(),initial.size()*sizeof(A),cudaMemcpyHostToDevice));}std::vector<A>host(){std::vector<A>a(initial.size());C(cudaMemcpy(a.data(),base,a.size()*sizeof(A),cudaMemcpyDeviceToHost));return a;}void append(std::vector<double>&out){for(A v:host())out.push_back(v);}bool guards(){auto h=host();for(int i=0;i<16;i++)if(h[i]!=initial[i]||h[h.size()-1-i]!=initial[initial.size()-1-i])return false;return true;}~Buffer(){cudaFree(base);}};
int main(){if(study_state_bytes()!=48)return 2;auto yy=read_file<int>("y_i32.bin",N);auto nn=read_file<float>("n_f32.bin",N);Buffer<int>y(yy,1234567);Buffer<float>n(nn,-999),theta(std::vector<float>(N,0),-999),flat(std::vector<float>(BLOCKS,0),-999),logs(std::vector<float>(BLOCKS,0),-999);Buffer<unsigned>state(std::vector<unsigned>(N*12,0),0xdeadbeef);auto reset=[&](){y.reset();n.reset();theta.reset();flat.reset();logs.reset();state.reset();C(study_seed_states(state.ptr,N));study_reset();};auto launch=[&](float a,float b){C(study_native_launch(state.ptr,theta.ptr,y.ptr,n.ptr,a,b,N,flat.ptr,logs.ptr));};reset();launch(20,1); // exactkernels warmup
for(int trial=1;trial<=5;trial++){reset();std::vector<double>out={N,STEPS,256,BLOCKS,123,20,1};y.append(out);n.append(out);theta.append(out);state.append(out);flat.append(out);logs.append(out);if(out.size()!=PREFIX){fprintf(stderr,"prefix%zu\n",out.size());return 3;}float a=20,b=1;double total=0,maxerr=0;bool good=true;for(int step=0;step<STEPS;step++){auto before=state.host();float olda=a,oldb=b;C(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();launch(a,b);total+=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();auto after=state.host();auto ht=theta.host();auto hf=flat.host();auto hl=logs.host();double e=0;int bad=study_check(before.data()+16,after.data()+16,ht.data()+16,yy.data(),nn.data(),a,b,N,&e);maxerr=fmax(maxerr,e);good=good&&bad==0;float fs=0,ls=0;for(int j=0;j<BLOCKS;j++){float ft[256],lt[256];for(int k=0;k<256;k++){int id=j*256+k;ft[k]=id<N?ht[16+id]:0;lt[k]=id<N?logf(ht[16+id]):0;}for(int stride=128;stride>0;stride/=2)for(int k=0;k<stride;k++){ft[k]+=ft[k+stride];lt[k]+=lt[k+stride];}good=good&&fabs(double(ft[0])-hf[16+j])<=2e-4&&fabs(double(lt[0])-hl[16+j])<=2e-4;fs+=hf[16+j];ls+=hl[16+j];}study_feedback(&a,&b,N,fs,ls);good=good&&std::isfinite(a)&&std::isfinite(b)&&a>0&&b>0&&y.guards()&&n.guards()&&theta.guards()&&flat.guards()&&logs.guards()&&state.guards();out.insert(out.end(),{double(step),double(olda),double(oldb),double(a),double(b),double(fs),double(ls),double(bad),e});theta.append(out);flat.append(out);logs.append(out);state.append(out);if(!good){fprintf(stderr,"oraclefailure step%d bad%d err%.17g\n",step,bad,e);break;}}good=good&&out.size()==COUNT;std::string path=std::string(getenv("STUDY_OUTPUT_DIR"))+"/gibbs_trial"+std::to_string(trial)+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)out.data(),out.size()*8);f.close();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.17g,\"max_rel_error\":null,\"jit_excluded\":true,\"timing_region\":\"sum32conditional_sampling_reduction_GPUcompletion_excludes_hostfeedback_capture\",\"internal_repeats\":32,\"iterations\":32,\"kernel_launches\":64,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,total,good?"true":"false",out.size(),maxerr,path.c_str(),out.size());fflush(stdout);if(!good)return 4;}return 0;}
